import * as THREE from 'three';
export function maquetteCamera137(camera,controls,model){model.updateWorldMatrix(true,true);const box=new THREE.Box3().setFromObject(model),center=box.getCenter(new THREE.Vector3()),radius=box.getSize(new THREE.Vector3()).length()/2;camera.fov=32;const half=Math.atan(Math.tan(THREE.MathUtils.degToRad(16))*Math.min(1,Math.max(.3,camera.aspect))),distance=radius/Math.sin(half)*1.06;camera.position.copy(center).add(new THREE.Vector3(1,.85,-1).normalize().multiplyScalar(distance));controls.target.copy(center);controls.maxDistance=Math.max(70,distance*1.5);camera.updateProjectionMatrix();controls.update();}
export function architecture137(view,maquette){if(!view.architecture137){view.architecture137=[];for(const root of[view.parts.get('roof'),view.model.userData.frontWall])root.traverse(o=>{if(!o.isMesh)return;const originals=Array.isArray(o.material)?o.material:[o.material],materials=originals.map(m=>{if(root===view.parts.get('roof')&&!/Concreto|Cubierta/i.test(m.name))return m;const copy=m.clone();view.architecture137.push({mesh:o,castShadow:o.castShadow,material:copy,opacity:m.opacity,transparent:m.transparent,depthWrite:m.depthWrite});return copy;});o.material=Array.isArray(o.material)?materials:materials[0];});}for(const row of view.architecture137){row.mesh.castShadow=maquette?false:row.castShadow;row.material.opacity=maquette ? .12 : row.opacity;row.material.transparent=maquette||row.transparent;row.material.depthWrite=maquette?false:row.depthWrite;row.material.needsUpdate=true;}view.dialog.querySelector('[data-sr-home]')?.setAttribute('aria-pressed',String(maquette));}
export function installMaquetteUI137(view){const d=view.dialog,doc=d.ownerDocument||document;d.dataset.srPanel137='false';const tabs=d.querySelector('.sr128-mode-tabs');const toggle=doc.createElement('button');toggle.type='button';toggle.dataset.srPanel137='';toggle.textContent='Equipos y detalles';toggle.setAttribute('aria-expanded','false');toggle.addEventListener('click',()=>{const open=d.dataset.srPanel137!=='true';d.dataset.srPanel137=String(open);toggle.setAttribute('aria-expanded',String(open));view.resize();});tabs.append(toggle);
 const tour=doc.createElement('div');tour.className='sr137-tour';tour.innerHTML='<button data-sr137-prev aria-label="Equipo anterior">←</button><button data-sr137-next>Explorar equipos →</button><span data-sr137-count></span>';d.querySelector('.sr126-tools').prepend(tour);let index=-1;const ids=[...view.parts.keys()];const go=delta=>{if(view.service128?.active)return;index=(index+delta+ids.length)%ids.length;const id=ids[index];view.isolated=false;d.dataset.srPanel137='true';toggle.setAttribute('aria-expanded','true');view.resize();view.select(id,true);tour.querySelector('[data-sr137-count]').textContent=(index+1)+' / '+ids.length;view.resize();};tour.querySelector('[data-sr137-prev]').addEventListener('click',()=>go(-1));tour.querySelector('[data-sr137-next]').addEventListener('click',()=>go(1));d.addEventListener('keydown',e=>{if(view.service128?.active||e.repeat||e.ctrlKey||e.altKey||e.metaKey||['INPUT','SELECT','TEXTAREA'].includes(e.target?.tagName))return;const k=e.key.toLowerCase();if(k==='home'||k==='f'||k==='e'){e.preventDefault();e.stopImmediatePropagation();if(k==='home')view.home();else if(k==='f'&&view.selected)view.focus(view.parts.get(view.selected));else if(k==='e'){const rows=view.cabinets135.rows.filter(r=>r.id===view.selected),open=rows.some(r=>!r.open);for(const r of rows)r.open=open;view.cabinets135.render();}}},true);}
